#include "advguard.h"
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>

std::vector<double> parseCSVLine(const std::string& line) {
    std::vector<double> features;
    std::stringstream ss(line);
    std::string value;
    while (std::getline(ss, value, ',')) {
        features.push_back(std::stod(value));
    }
    return features;
}

int main(int argc, char* argv[]) {
    // Setup for 29 continuous features (Kaggle Credit Card Fraud dataset)
    AdvGuardEngine engine(29, 5, 3, 1.0, 0.6);
    
    // Load historical data from CSV generated by Python
    std::vector<Transaction> history;
    std::string history_file = "../ml_baseline/data/historical_history.csv";
    std::ifstream h_file(history_file);
    if (h_file.is_open()) {
        std::string line;
        int id_counter = 0;
        while (std::getline(h_file, line)) {
            std::vector<double> vals = parseCSVLine(line);
            if (vals.size() >= 30) { // 29 features + 1 label
                Transaction t;
                t.id = "HIST_" + std::to_string(id_counter++);
                // Features are the first 29 values
                t.features = std::vector<double>(vals.begin(), vals.begin() + 29);
                // Label is the 30th value
                t.is_fraud = (vals[29] == 1.0);
                history.push_back(t);
            }
        }
    } else {
        std::cerr << "Could not open " << history_file << ". Did you run train_and_attack.py first?\n";
        return 1;
    }
    engine.loadHistoricalData(history);
    
    // Evaluate the evasion sample generated by Python
    std::string evasion_file = (argc >= 2) ? argv[1] : "../ml_baseline/data/evasion_sample.csv";
    std::ifstream ev_file(evasion_file);
    
    if (ev_file.is_open()) {
        std::string line;
        if (std::getline(ev_file, line)) {
            Transaction evasion_txn;
            evasion_txn.id = "SUSPECT_TXN_001";
            evasion_txn.features = parseCSVLine(line);
            evasion_txn.is_fraud = false; // The vulnerable ML thought it was safe!
            
            std::string report;
            bool blocked = engine.evaluateTransaction(evasion_txn, report);
            
            std::cout << "=== ADVGUARD FORENSIC REPORT ===\n";
            std::cout << "Status: " << (blocked ? "BLOCKED (OVERRIDDEN)" : "APPROVED") << "\n\n";
            std::cout << report;
            std::cout << "=== END REPORT ===\n";
        }
    } else {
        std::cerr << "Could not open " << evasion_file << "\n";
        return 1;
    }
    
    return 0;
}
